edits.replacement:
.ui-key.pill{ border-radius:12px; padding:0 9px; }
/* vNN.xx, UI REDESIGN ui5q1q (his #50, from the lint of the Mainframe YOUR STATS shot): the caption over the run log (EVERY RUN,
   NEWEST FIRST) took the dark ink meant for the cream cards and read at about 3:1 on the graphite page; it is the second text
   colour there now. The cream cards keep their ink. */
#root #opane_rec .crlab{ color:var(--tx-2); }

check:
{v:'VER',what:'his #50 (UI redesign ui5q1q, from the lint of the Mainframe YOUR STATS shot): on the stats page a caption on the graphite is not in the dark ink of the cream cards, and the page is marked as a page that scrolls',
 run:function(){
   var p=document.getElementById('opane_rec'), bad=[], c, el;
   if(!p) return 'SKIP: no stats page here';
   el=p.querySelector('.crlab');
   if(!el){ el=document.createElement('div'); el.className='crlab'; el.textContent='A CAPTION '+'FOR THE CHECK'; p.appendChild(el); c=getComputedStyle(el).color; p.removeChild(el); }
   else c=getComputedStyle(el).color;
   if(c==='rgb(106, 101, 90)') bad.push('a caption on the stats page is in the dark card ink ('+c+')');
   if(!p.hasAttribute('data-lint-scroll')) bad.push('the stats page is not marked as a page that scrolls');
   return bad.length?bad.join('; '):null; }},
